-- ================================================================
INSERT INTO "dietary" ("id", "name")
VALUES
    (gen_random_uuid(), 'vegetarian'),
    (gen_random_uuid(), 'vegan'),
    (gen_random_uuid(), 'glutenFree'),
    (gen_random_uuid(), 'dairyFree'),
    (gen_random_uuid(), 'veryHealthy'),
    (gen_random_uuid(), 'lowFodmap')
ON CONFLICT ("name") DO NOTHING;

