-- ================================================================
-- 3. Recettes (idempotent par titre)
-- ================================================================
INSERT INTO "recipes" ("id", "title", "summary", "author_id", "preparation_minutes",
                       "step_by_step_instructions", "image_url", "status", "created_at", "updated_at")
SELECT
    gen_random_uuid(),
    d.title,
    d.summary,
    (SELECT "id" FROM "users" WHERE "username" = 'ForkEat'),
    NULLIF(d.prep_min, '')::INTEGER,
    d.steps::JSONB,
    NULLIF(d.image_url, ''),
    'PUBLISHED',
    NOW(),
    NOW()
FROM (VALUES
    ('Pilaf de riz complet aux champignons'::TEXT, 'Le pilaf de riz brun et champignons pourrait être exactement le petit atout que vous recherchez. Une portion de ce plat contient environ 5g de protéines, 5g de matières grasses et un total de 228 calories. Cette recette en fait 4. Pour 65 cents la portion, cette recette couvre 11 % de vos besoins quotidiens en vitamines et minéraux. Cette recette de Foodista nécessite de l’oignon, du riz complet, du poivre moulu et de l’huile de tournesol non raffinée. Quelques personnes ont fait cette recette, et quinze diraient que dis-le parfait. De la préparation à l’assiette, cette recette prend environ 45 minutes. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers, lacto-ovo-végétarien et végétalien. Globalement, cette recette obtient un score super cuillère de 93 %. Des recettes similaires incluent le pilaf riz brun et champignons, le riz complet rapide et le pilaf aux champignons, et le pilaf au riz complet.'::TEXT, '45'::TEXT, '[{"step_number": 1, "instruction": "Chauffez de l’huile dans une grande casserole à feu moyen. Saut coupé de l’oignon et des champignons tranchés pendant 5 minutes.", "duration": {"number": 5, "unit": "minutes"}, "equipment": ["casserole"], "ingredients": ["champignons", "oignon", "huile de cuisson"]}, {"step_number": 2, "instruction": "Ajoutez du riz complet et remuez pour enrober d’huile.", "duration": null, "equipment": [], "ingredients": ["riz brun", "huile de cuisson"]}, {"step_number": 3, "instruction": "Ajoutez de l’eau.", "duration": null, "equipment": [], "ingredients": ["eau"]}, {"step_number": 4, "instruction": "Portez à ébullition, puis laissez mijoter pendant 30 minutes.", "duration": {"number": 30, "unit": "minutes"}, "equipment": [], "ingredients": []}, {"step_number": 5, "instruction": "Retirez du feu et couvrez avec un couvercle.", "duration": null, "equipment": [], "ingredients": []}, {"step_number": 6, "instruction": "Laissez reposer jusqu’à ce que tout le liquide soit absorbé.", "duration": null, "equipment": [], "ingredients": []}]'::TEXT, 'https://img.spoonacular.com/recipes/636292-556x370.jpg'::TEXT),
    ('Riz pilaf', 'Le Rice Pilaf est un amusement sans produits laitiers. Cette recette contient 4 portions avec 201 calories, 5g de protéines et 3g de matières grasses chacune. Pour 58 cents la portion, cette recette couvre 4 % de vos besoins quotidiens en vitamines et minéraux. Un mélange de consommé de bœuf, de beurre, d’oncle ben’s et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi savoureuse. Cette recette de Foodista a 1 fan. De la préparation à l’assiette, cette recette prend environ 45 minutes. Avec un score cuillère de 29 %, ce plat est plutôt mauvais. Le pilaf de riz aux pignons de pin (pilaf de riz au piñon), le pilaf de riz maison (Riz à roni sain) et le pilaf de riz maison (Riz à roni sain) sont très similaires à cette recette.', '45', '[{"step_number": 1, "instruction": "Mélangez tous les ingrédients.", "duration": null, "equipment": [], "ingredients": []}, {"step_number": 2, "instruction": "Faites cuire à 350 degrés pendant 45 minutes.", "duration": {"number": 45, "unit": "minutes"}, "equipment": ["four"], "ingredients": []}]', 'https://img.spoonacular.com/recipes/658277-556x370.jpg'),
    ('Pudding au chocolat crémeux avec crème fouettée à la noix de coco', 'Si vous souhaitez ajouter à votre collection plus de recettes sans gluten, sans produits laitiers et adaptées aux FODMAP, Pudding au chocolat crémeux avec crème fouettée à la noix de coco pourrait être une recette à essayer. Une portion contient 844 calories, 25 g de protéines et 69 g de matières grasses. Cette recette en fait 2. Pour 3,14 $ la portion, cette recette couvre 18 % de vos besoins quotidiens en vitamines et minéraux. 5 personnes ont fait cette recette et la referaient. Un mélange de lait de coco, de pépites de chocolat, de copeaux de chocolat et de quelques autres ingrédients suffisent pour rendre cette recette aussi délicieuse. Seules quelques personnes ont vraiment aimé ce dessert. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. Dans l’ensemble, cette recette obtient un bon score cuillère de 65 %. Essayez le pudding au chocolat avec de la crème fouettée à l’espresso, le pudding au chocolat avec de la crème fouettée à l’espresso, et le pudding au chocolat à la stout avec de la crème fouettée à la bière pour des recettes similaires.', '45', '[{"step_number": 1, "instruction": "Faites fondre le chocolat dans un contenant compatible micro-ondes avec du lait non lait.", "duration": null, "equipment": ["micro-ondes"], "ingredients": ["substitut de lait", "chocolat"]}, {"step_number": 2, "instruction": "Ajoutez du chocolat fondu avec du tofu dans un blender (j’utilise une solution miracle).", "duration": null, "equipment": ["mélangeur"], "ingredients": ["chocolat", "tofu"]}, {"step_number": 3, "instruction": "Mélangez jusqu’à ce qu’il soit lisse.", "duration": null, "equipment": [], "ingredients": []}, {"step_number": 4, "instruction": "Mettez-les dans des plats de service.", "duration": null, "equipment": [], "ingredients": []}]', 'https://img.spoonacular.com/recipes/640625-556x370.jpg'),
    ('Salade de courgettes et coquelicots', 'La salade de courgettes et coquelicots est une recette végétarienne sans gluten, sans produits laitiers, paléolithique et lacto ovo, avec 1 portion. Une portion de ce plat contient environ 3 g de protéines, 30 g de matières grasses et un total de 334 calories. Pour 1,41 $ la portion, cette recette couvre 9 % de vos besoins quotidiens en vitamines et minéraux. Cette recette de Foodista nécessite de la courgette, de l’ail, du jus de citron et de l’huile de noix. Une personne était contente d’avoir essayé cette recette. Il fonctionne mieux comme un amusement d’œuvre, et se termine en environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 56 %. Cette partition est plutôt bonne. Si vous aimez cette recette, jetez un œil à ces recettes similaires : pain aux graines de cocourgette aux graines de pavot citron, muffins aux graines de pavot citron et courgettes, et pain aux graines de courgettes aux graines de pavot citron.', '45', '[{"step_number": 1, "instruction": "Rincez et séchez la courgette.", "duration": null, "equipment": [], "ingredients": ["courgettes"]}, {"step_number": 2, "instruction": "Coupez les deux extrémités et râpez les courgettes en longues fines lanières.", "duration": null, "equipment": [], "ingredients": ["courgettes"]}, {"step_number": 3, "instruction": "Placez-les dans un grand saladier.", "duration": null, "equipment": ["bol"], "ingredients": []}, {"step_number": 4, "instruction": "Fouetter ensemble l’huile de noix, le jus de citron, le miel, l’ail écrasé, les graines de pavot, le sel et le poivre dans un bol. Mélangez les lamelles de courgette avec la vinaigrette jusqu’à ce que ce soit bien combiné.", "duration": null, "equipment": ["fouet", "bol"], "ingredients": ["sel et poivre", "jus de citron", "Graines de pavot", "Huile de noix", "courgettes", "ail", "miel"]}, {"step_number": 5, "instruction": "Servez dès que possible.", "duration": null, "equipment": [], "ingredients": []}]', 'https://img.spoonacular.com/recipes/656681-556x370.jpg'),
    ('Salade japonaise de concombre', 'On n’a jamais trop de recettes japonaises, alors essayez la salade japonaise de concombre. Cette recette contient 4 portions avec 26 calories, 1g de protéines et 1g de matières grasses chacune. Pour 30 cents la portion, cette recette couvre 3 % de vos besoins quotidiens en vitamines et minéraux. Cette recette de Foodista a 1 fan. Un mélange de concombre, de sauce soja, d’huile de sésame et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi savoureuse. Il fonctionne mieux en accompagnement, et se fait en environ 45 minutes. C’est une bonne option si vous suivez un régime sans gluten ni produits laitiers. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 42 %, ce qui est positif. Des recettes similaires incluent la salade japonaise de concombre, la salade japonaise de concombre et la salade japonaise de concombre.', '45', '[{"step_number": 1, "instruction": "Mélangez tous les ingrédients dans un grand bol ; Jetez jusqu’à ce que ce soit combiné. Cette recette donne 4 portions. Commentaires : Essayez d’acheter des concombres anglais, aussi appelés concombres sans pépins, au lieu des concombres classiques. Bien qu’elles ne soient pas réellement sans pépins, les graines sont plus petites et la chair plus ferme. Description : « Cette salade légère et rafraîchissante accompagne parfaitement les viandes grillées ou rôties. »", "duration": null, "equipment": ["bol"], "ingredients": ["concombre", "graines"]}]', 'https://img.spoonacular.com/recipes/648467-556x370.jpg'),
    ('Avoine Salée', 'Salé à l’Avoine pourrait être exactement la recette végétarienne sans gluten, sans produits laitiers et lacto ovo que vous cherchez. Pour 1,05 $ la portion, cette recette couvre 18 % de vos besoins quotidiens en vitamines et minéraux. Cette recette contient 1 portion contenant 311 calories, 18g de protéines et 11g de matières grasses chacune. Il est présenté par Foodista. Une personne a essayé et aimé cette recette. Si vous avez de la sriracha, de l’eau, de l’oignon et quelques autres ingrédients sous la main, vous pouvez en préparer. Peu de gens ont vraiment aimé ce plat principal. De la préparation à l’assiette, cette recette prend environ 45 minutes. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 52 %, ce qui est positif. Si vous aimez cette recette, vous pourriez aussi apprécier des recettes comme les Avoines Salées, les Avoines Salées au Brie et aux Tomates Cerises, et les Avoines Chianes Salées avec Salsa, Avocat et Œufs Au Plat.', '45', '[{"step_number": 1, "instruction": "Faites bouillir 1 tasse d’eau. Incorporez l’avoine et faites cuire en remuant fréquemment à feu moyen jusqu’à ce que ce soit épaissi et crémeux, environ 1 à 30 minutes. Couvre l’avoine et retire la marmite du feu.", "duration": {"number": 2, "unit": "minutes"}, "equipment": ["pot"], "ingredients": ["eau", "avoine"]}, {"step_number": 2, "instruction": "Chauffez une petite poêle à feu moyen ; Endendrez uniformément avec un spray de cuisson. Cassez l’œuf dans la poêle et faites cuire environ 3 minutes, ou jusqu’à ce que les blancs deviennent opaques et que le jaune soit légèrement durci, mais encore liquide.", "duration": {"number": 3, "unit": "minutes"}, "equipment": ["poêle à frire"], "ingredients": ["pulvérisateur de cuisson", "jaune d''œuf", "œuf"]}, {"step_number": 3, "instruction": "Retirez l’œuf et mettez de côté ; Ajoutez des oignons en dés et faites revenir jusqu’à ce que cela soit tendre.", "duration": null, "equipment": [], "ingredients": ["oignon", "œuf"]}, {"step_number": 4, "instruction": "Ajoutez la sauce soja et la Sriracha à l’avoine ; Remuez pour mélanger. Versez de l’avoine dans un bol et garnissez d’oignons en dés et d’œufs au plat.", "duration": null, "equipment": ["bol"], "ingredients": ["sauce de soja", "Sriracha", "farine d''avoine", "oignon", "avoine", "œuf"]}, {"step_number": 5, "instruction": "Arrosez d’huile de sésame et de sauce soja.", "duration": null, "equipment": [], "ingredients": ["Huile de sésame", "sauce de soja"]}]', 'https://img.spoonacular.com/recipes/659480-556x370.jpg'),
    ('Parfait au yaourt fruité', 'Vous avez besoin d’un petit-déjeuner végétarien sans gluten, lacto ovo et primal ? Le parfait au yaourt fruité pourrait être une recette incroyable à essayer. Cette recette en fait 3. Une portion de ce plat contient environ 4g de protéines, 3g de matières grasses et un total de 95 calories. Pour 96 cents la portion, cette recette couvre 8 % de vos besoins quotidiens en vitamines et minéraux. Peu de gens ont fait cette recette, et je dirais que ça a été juste. Cette recette de Foodista nécessite du yaourt, du jus d’orange, du kiwi et de la mangue. De la préparation à l’assiette, cette recette prend environ 45 minutes. Avec un score cuillère de 55 %, ce plat est solide. Essayez la recette de parfaits fruits et yaourt (parfait raisins et granola), le parfait fruité de cailloux et le parfait au yaourt à l’amarante – parfait à l’amarante avec des fruits pour des recettes similaires.', '45', '[{"step_number": 1, "instruction": "Il suffit de superposer des fruits frais et du yaourt dans un joli verre", "duration": null, "equipment": [], "ingredients": ["fruits", "yaourt"]}, {"step_number": 2, "instruction": "Ajoutez plus de fruits mélangés sur le dessus et servez.", "duration": null, "equipment": [], "ingredients": ["Fruits mélangés"]}]', 'https://img.spoonacular.com/recipes/644045-556x370.jpg'),
    ('Foie de bœuf avec oignons et bacon', 'Si vous souhaitez ajouter plus de recettes sans gluten et primitives à votre répertoire, Beef Liver With Onions and Bacon pourrait être une recette à essayer. Une portion contient 551 calories, 39 g de protéines et 34 g de matières grasses. Cette recette en sert 4 et coûte 1,57 $ la portion. Cela fonctionne bien comme plat principal assez abordable. Cette recette de Foodista a 1 fan. Rendez-vous au magasin et achetez du sel et du poivre, du lait, du bacon et quelques autres choses pour le préparer aujourd’hui. De la préparation à l’assiette, cette recette prend environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 85 %. Cette partition est excellente. Des recettes similaires incluent le foie de bœuf avec oignons et bacon, le foie de bœuf avec figues, bacon et compote d’oignon caramélisé, et le foie de bœuf avec figues, bacon et compote d’oignon caramélisé.', '45', '[{"step_number": 1, "instruction": "Placez le foie dans un grand bol et ajoutez assez de lait pour couvrir ; Mettez de côté et laissez tremper pendant 30 minutes.", "duration": {"number": 30, "unit": "minutes"}, "equipment": ["bol"], "ingredients": ["foie", "lait"]}, {"step_number": 2, "instruction": "Chauffez une grande poêle lourde, de préférence en fonte, à feu moyen-doux et faites cuire le bacon jusqu’à ce qu’il soit juste croustillant.", "duration": null, "equipment": ["poêle à frire"], "ingredients": ["bacon"]}, {"step_number": 3, "instruction": "Retirez avec une cuillère à fentes et réservez sur une assiette ; Tiens-toi au chaud.", "duration": null, "equipment": ["cuillère à fente"], "ingredients": []}, {"step_number": 4, "instruction": "Retirez toutes les cuillères à soupe de graisse de bacon de la poêle sauf environ 2 cillerées.  À feu moyen-doux à feu, faites cuire l’oignon jusqu’à ce qu’il soit tendre, translucide et parfumé, mais pas doré.", "duration": null, "equipment": ["poêle à frire"], "ingredients": ["Gouttes de bacon", "oignon"]}, {"step_number": 5, "instruction": "Retirez avec une cuillère à fente et ajoutez le bacon à l’assiette ; Tiens-toi au chaud.", "duration": null, "equipment": ["cuillère à fente"], "ingredients": ["bacon"]}, {"step_number": 6, "instruction": "Égouttez le lait du foie, séchez et saupoudrez de sel et de poivre.", "duration": null, "equipment": [], "ingredients": ["sel et poivre", "foie", "lait"]}, {"step_number": 7, "instruction": "Remet la graisse de bacon réservée dans la poêle.  Faites cuire doucement les tranches de foie dans la graisse de bacon à feu moyen-bas jusqu’à ce qu’elles soient à peine rosées à l’intérieur, environ 3 ou 4 minutes de chaque côté.", "duration": {"number": 4, "unit": "minutes"}, "equipment": ["poêle à frire"], "ingredients": ["Gouttes de bacon", "foie"]}, {"step_number": 8, "instruction": "Servez immédiatement, nappé d’oignons et de bacon.", "duration": null, "equipment": [], "ingredients": ["oignon", "bacon"]}]', 'https://img.spoonacular.com/recipes/634625-556x370.jpg'),
    ('Glaçage au beurre à la vanille à l’ancienne', 'Le glaçage Old Fashioned Vanille et Crème au Beurre est un glaçage qui peut servir 8 personnes. Tu fais attention à ta silhouette ? Cette recette sans gluten contient 512 calories, 0 g de protéines et 24 g de matières grasses par portion. Pour 53 cents la portion, cette recette couvre 1 % de vos besoins quotidiens en vitamines et minéraux. 1429 personnes ont été impressionnées par cette recette. Si vous avez du sucre à glace, du beurre, de la vanille et quelques autres ingrédients sous la main, vous pouvez le préparer. Il est présenté par Pink When. De la préparation à l’assiette, cette recette prend environ 5 minutes. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 9 %. Ce score est améliorable. Parmi les recettes similaires figurent le gâteau d’anniversaire à la vanille avec crème au beurre à la vanille à l’ancienne, le glaçage à la crème au beurre à la vanille et le glaçage au fromage frais à la fraise, et les mini cupcakes à la vanille avec glaçage à la crème au beurre à la vanille.', '5', '[{"step_number": 1, "instruction": "Recette de glaçage au beurre", "duration": null, "equipment": [], "ingredients": ["givrage"]}, {"step_number": 2, "instruction": "Dans un grand saladier à mélanger, du beurre à la crème et du graisse avec un batteur électrique.", "duration": null, "equipment": ["mélangeur à main", "bol mélangeur"], "ingredients": ["raccourcissement", "beurre", "crème"]}, {"step_number": 3, "instruction": "Ajoutez la vanille.", "duration": null, "equipment": [], "ingredients": ["vanille"]}, {"step_number": 4, "instruction": "Ajoutez progressivement du sucre à glace tamisé, une tasse à la fois, en battant à vitesse moyenne.", "duration": null, "equipment": [], "ingredients": ["sucre en poudre"]}, {"step_number": 5, "instruction": "Grattez souvent les côtés et le fond du bol. Lorsque tout le sucre est mélangé, le glaçage paraît sec.", "duration": null, "equipment": ["bol"], "ingredients": ["givrage", "sucre"]}, {"step_number": 6, "instruction": "Ajoutez le lait et battez à vitesse moyenne pendant 3 minutes.", "duration": {"number": 3, "unit": "minutes"}, "equipment": [], "ingredients": ["lait"]}, {"step_number": 7, "instruction": "Gardez le glaçage couvert d’un chiffon humide jusqu’à ce qu’il soit prêt à être décoré. Pour de meilleurs résultats, gardez le bol à glaçage au réfrigérateur quand vous ne l’utilisez pas.", "duration": null, "equipment": ["bol"], "ingredients": ["givrage"]}, {"step_number": 8, "instruction": "Le glaçage peut être conservé dans un récipient hermétique pendant jusqu’à une semaine. Il suffit de le refouetter dans votre batteur avant de l’utiliser. Ça fait 3 tasses et demie.", "duration": null, "equipment": ["mélangeur"], "ingredients": ["givrage"]}]', 'https://img.spoonacular.com/recipes/715550-556x370.jpg'),
    ('Pesto simple à la sauge', 'Simple Sage Pesto est une recette sans gluten et primitive en 8 portions. Une portion contient 95 calories, 3g de protéines et 9g de matières grasses. Pour 95 cents la portion, cette recette couvre 8 % de vos besoins quotidiens en vitamines et minéraux. Peu de gens ont fait cette recette, et je dirais que ça a été juste. Un mélange de feuilles de sauge, de gousses d’ail, de sel et de poivre, et d’une poignée d’autres ingrédients suffisent pour rendre cette recette aussi délicieuse. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. Ça fonctionne bien comme condiment. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 63 %, ce qui est solide. Des recettes similaires incluent le Goudan simple et les biscuits à la sauge, le chou-rave simple aux pistaches et à la sauge, et le pesto à la sauge et aux noix.', '45', '[{"step_number": 1, "instruction": "Dans le bol d’un robot culinaire (ou au blender), ajoutez la sauge, l’ail et les pignons.  Faites pulser les ingrédients plusieurs fois jusqu’à ce qu’ils soient hachés. En un flux régulier, ajoutez lentement l’huile d’olive pendant que le robot culinaire ou le blender fonctionne.  Arrêtez-vous pour gratter les côtés une fois avec une spatule en caoutchouc et ajoutez le sel et le poivre.  Faites tourner le processeur encore quelques secondes pour bien combiner.", "duration": null, "equipment": ["processeur alimentaire", "mélangeur", "spatule", "bol"], "ingredients": ["sel et poivre", "huile d''olive", "pignons de pin", "ail", "sauge"]}, {"step_number": 2, "instruction": "Transférez le pesto dans un récipient hermétique et conservez-le au réfrigérateur jusqu’à ce qu’il soit prêt à être utilisé.  Le pesto se conserve au réfrigérateur jusqu’à 5 jours.", "duration": null, "equipment": [], "ingredients": ["Pesto"]}]', 'https://img.spoonacular.com/recipes/660130-556x370.jpg'),
    ('Bacon Wrapped Filet Mignon', 'Vous ne pouvez jamais avoir trop de recettes de plat d''appoint, alors essayez Bacon Wrapped Filet Mignon. Cette recette sert 4 et coûte 39 cents par portion. Tu regardes ta figure ? Cette recette sans gluten, sans lait, paléolithique et primal contient 98 calories, 3g de protéines et 9g de graisse par portion. Allez au magasin et prenez du sel et du poivre, du bacon, de l''ail et quelques autres choses pour le faire aujourd''hui. 61 personnes ont fait cette recette et la referaient. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 13%, ce qui n''est pas si exceptionnel. Les utilisateurs qui ont aimé cette recette ont également aimé Bacon Wrapped Filet Mignon, Bacon Wrapped Filet Mignon et Bacon Wrapped Filet Mignon.', '45', '[{"step_number": 1, "instruction": "Placer les filets sur un grand plat et envelopper une tranche de bacon à température ambiante autour de chaque filet, en étirant doucement le bacon si nécessaire. Sécurisez les extrémités du bacon avec un cure-dent.", "duration": null, "equipment": ["cure-dents"], "ingredients": ["bacon", "enveloppe"]}, {"step_number": 2, "instruction": "Couper les gousses d''ail en deux et frotter les deux côtés de chaque filet avec les extrémités coupées de l''ail. Assaisonner bien avec du sel et du poivre des deux côtés.", "duration": null, "equipment": [], "ingredients": ["sel et poivre", "gousses d''ail entières", "ail", "broyage sec"]}, {"step_number": 3, "instruction": "Préchauffer le gril à très chaud. Avec des pinces, placez chaque steak sur le grill et faites cuire 3-4 minutes à mi-chemin pour obtenir de belles marques de grill.", "duration": {"number": 4, "unit": "minutes"}, "equipment": ["grille", "pinces"], "ingredients": ["steak"]}, {"step_number": 4, "instruction": "Retournez les steaks et faites cuire encore 3-4 minutes.", "duration": {"number": 4, "unit": "minutes"}, "equipment": [], "ingredients": ["steak"]}, {"step_number": 5, "instruction": "Retirer du gril et laisser reposer abondamment couvert pendant 5 minutes avant d''enlever les cure-dents et de servir.", "duration": {"number": 5, "unit": "minutes"}, "equipment": ["cure-dents", "grille"], "ingredients": []}, {"step_number": 6, "instruction": "Servir tel quel ou avec des champignons d''ail salés", "duration": null, "equipment": [], "ingredients": ["champignons", "ail"]}]', 'https://img.spoonacular.com/recipes/633338-556x370.jpg'),
    ('Morceau de pain en croûte', 'Culotte de pain La morue prend environ 45 minutes du début à la fin. Une portion de ce plat contient environ 3g de protéines, 3g de graisses et un total de 94 calories. Cette recette sert 6 $ et coûte 11 cents par portion. Cette recette est appréciée par 1 foodies et cuisiniers. Cette recette de Foodista nécessite de l''huile d''olive, des miettes de pain, du cerveau, du sel et du poivre. C''est une bonne option si vous suivez un régime sans lait et pescatarien. Il fonctionne bien comme un hor d''oeuvre bon marché. Avec un score cuilleraculaire de 42%, ce plat est solide. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes telles que Sole croûte, Tilapie croûte et Clams croûte.', '45', '[{"step_number": 1, "instruction": "Assaisonner le pain frais miettes avec le cervil, sel et poivre.", "duration": null, "equipment": [], "ingredients": ["miettes de pain fraîches", "sel et poivre", "cerveau"]}, {"step_number": 2, "instruction": "Mettez de côté.", "duration": null, "equipment": [], "ingredients": []}, {"step_number": 3, "instruction": "Frotter la morue avec de l''huile d''olive.", "duration": null, "equipment": [], "ingredients": ["morue", "huile de cuisson", "broyage sec"]}, {"step_number": 4, "instruction": "Assaisonner de sel et de poivre.", "duration": null, "equipment": [], "ingredients": ["sel et poivre"]}, {"step_number": 5, "instruction": "Appuyez seulement sur le côté supérieur de la morue dans les miettes de pain assaisonnées.", "duration": null, "equipment": [], "ingredients": ["miettes de pain assaisonnées", "morue"]}, {"step_number": 6, "instruction": "C''est dur à enrober généreusement.", "duration": null, "equipment": [], "ingredients": []}, {"step_number": 7, "instruction": "Chauffer une grande poêle antiadhésive sur une poêle moyenne-élevée et ajouter 2 cuillères à soupe d''huile d''olive.", "duration": null, "equipment": ["poêle à frire"], "ingredients": ["huile d''olive"]}, {"step_number": 8, "instruction": "Placer le côté de la chapelure vers le bas, faire revenir le poisson pendant environ 3 à 5 minutes.", "duration": {"number": 5, "unit": "minutes"}, "equipment": [], "ingredients": ["chapelure", "poisson"]}, {"step_number": 9, "instruction": "Vous verrez le poisson commencer à tourner de cru à un blanc opaque, ce qui vous permet de savoir quand le tourner.", "duration": null, "equipment": [], "ingredients": ["poisson"]}, {"step_number": 10, "instruction": "Retournez doucement le poisson et sachez encore 3 minutes.", "duration": {"number": 3, "unit": "minutes"}, "equipment": [], "ingredients": ["poisson"]}]', 'https://img.spoonacular.com/recipes/635944-556x370.jpg'),
    ('Lemon Pepper Steak', 'Lemon Pepper Steak est une recette sans gluten, sans lait, paléolithique et primal avec 36 portions. Cet hor d''oeuvre a 35 calories, 3g de protéines et 2g de graisse par portion. Pour 24 cents par portion, cette recette couvre 2 % de vos besoins quotidiens en vitamines et minéraux. Peu de gens ont fait cette recette, et je dirais qu''elle a atteint l''endroit. Il vous est apporté par Foodista. Il peut être apprécié à tout moment, mais il est particulièrement bon pour le jour de valentin. De la préparation à l''assiette, cette recette prend environ 45 minutes. Si vous avez du sel, de l''eau, du jus de citron et quelques autres ingrédients, vous pouvez le faire. Dans l''ensemble, cette recette gagne un très mauvais score (mais encore fixable) cuilleraculaire de 10%. Des recettes similaires comprennent le citron pepper Steak, le citron-pepper Flank Steak Tacos et les enrobes de poulet au citron poivré avec sauce au citron poivré.', '45', '[{"step_number": 1, "instruction": "Mélanger le jus de citron, le sel et l''herbe d''aneth. Trim tous les gras visibles et placer le steak de bœuf dans un sac ou un plat en plastique; ajouter la marinade, en se tournant vers le manteau. Sachet d''attache solidement ou couvrir le plat et mariner au réfrigérateur 6 à 8 heures ou toute la nuit, en tournant au moins une fois.", "duration": {"number": 480, "unit": "minutes"}, "equipment": ["sacs ziploc"], "ingredients": ["steak de poulet", "jus de citron", "aneth", "marinade", "bœuf", "sel"]}, {"step_number": 2, "instruction": "Retirer le steak de la marinade, presser le poivre dans la surface des deux côtés de la viande.", "duration": null, "equipment": [], "ingredients": ["marinade", "poivre", "steak", "viande"]}, {"step_number": 3, "instruction": "Déposer le steak sur la poêle à griller et faire griller 10 à 12 minutes de chaque côté. Couper le steak en tranches fines.", "duration": {"number": 10, "unit": "minutes"}, "equipment": ["poêle à griller"], "ingred